import React, { useState, useEffect, useRef, useContext } from 'react';
import { useParams, Link } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';
import Navbar from '../components/Navbar';
import { API_URL } from '../config';

const CoursePlayer = () => {
  const { id } = useParams();
  const { token } = useContext(AuthContext);
  const [course, setCourse] = useState(null);
  const [activeLessonIndex, setActiveLessonIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const videoRef = useRef(null);

  useEffect(() => {
    fetch(`${API_URL}/courses/${id}`)
      .then(res => { if (!res.ok) throw new Error('Cours introuvable.'); return res.json(); })
      .then(data => setCourse(data))
      .catch(err => setError(err.message))
      .finally(() => setLoading(false));
  }, [id]);

  useEffect(() => {
    // Recharge proprement la vidéo à chaque changement de leçon, en ignorant
    // les erreurs "aborted" qui surviennent normalement quand la source change vite.
    const videoEl = videoRef.current;
    if (videoEl) {
      videoEl.load();
      const playPromise = videoEl.play();
      if (playPromise !== undefined) {
        playPromise.catch(() => {
          // Lecture bloquée par le navigateur ou interrompue volontairement — sans gravité.
        });
      }
    }
  }, [activeLessonIndex, course]);

  const markLessonComplete = async (lessonId) => {
    if (!token) return;
    try {
      await fetch(`${API_URL}/courses/${id}/progress/${lessonId}`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
      });
    } catch {
      // silencieux — pas bloquant pour l'expérience de lecture
    }
  };

  const goToNextLesson = () => {
    if (!course) return;
    const current = course.lessons[activeLessonIndex];
    if (current) markLessonComplete(current.id);
    if (activeLessonIndex < course.lessons.length - 1) {
      setActiveLessonIndex(activeLessonIndex + 1);
    }
  };

  if (loading) {
    return <div className="min-h-screen text-white"><Navbar /><p className="text-slate-500 text-sm text-center py-32">Chargement...</p></div>;
  }

  if (error || !course || course.lessons.length === 0) {
    return (
      <div className="min-h-screen text-white">
        <Navbar />
        <div className="flex flex-col items-center justify-center py-32 gap-4">
          <p className="text-slate-500 text-sm">{error || 'Aucune leçon disponible pour ce cours.'}</p>
          <Link to="/dashboard" className="text-blue-400 hover:text-blue-300 font-semibold text-sm">← Retour à mon apprentissage</Link>
        </div>
      </div>
    );
  }

  const activeLesson = course.lessons[activeLessonIndex];
  const hasResume = course.resume_pdf_url && course.resume_pdf_url.trim() !== '';
  const hasTp = course.tp_pdf_url && course.tp_pdf_url.trim() !== '';

  return (
    <div className="min-h-screen text-white">
      <Navbar />

      <div className="max-w-6xl mx-auto px-6 py-10 grid lg:grid-cols-[1fr_320px] gap-8">
        <div>
          <div className="bg-black rounded-2xl overflow-hidden mb-6 aspect-video flex items-center justify-center">
            {activeLesson.video_url ? (
              <video
                ref={videoRef}
                key={activeLesson.id}
                controls
                autoPlay
                className="w-full h-full"
              >
                <source src={activeLesson.video_url} />
                Ton navigateur ne supporte pas la lecture vidéo.
              </video>
            ) : (
              <p className="text-slate-500 text-sm">Aucune vidéo n'a encore été ajoutée pour cette leçon.</p>
            )}
          </div>

          <div className="flex items-center justify-between mb-6">
            <div>
              <span className="text-[11px] font-semibold text-blue-400 uppercase tracking-wide">{course.title}</span>
              <h1 className="text-xl font-bold mt-1">{activeLesson.title}</h1>
            </div>
            {activeLessonIndex < course.lessons.length - 1 && (
              <button onClick={goToNextLesson} className="bg-white hover:bg-slate-100 text-slate-900 font-semibold text-sm px-5 py-2.5 rounded-lg transition-colors whitespace-nowrap">
                Leçon suivante →
              </button>
            )}
          </div>

          {(hasResume || hasTp) && (
            <div className="grid sm:grid-cols-2 gap-4">
              {hasResume && (
                <a href={course.resume_pdf_url} target="_blank" rel="noopener noreferrer"
                  className="flex items-center justify-between bg-slate-900/60 border border-slate-800 rounded-xl p-4 hover:border-blue-500/40 transition-colors">
                  <span className="text-sm font-semibold text-slate-200">Fiche Synthèse</span>
                  <span className="text-xs font-bold uppercase text-blue-400 bg-blue-500/10 px-3 py-1.5 rounded-lg">Télécharger</span>
                </a>
              )}
              {hasTp && (
                <a href={course.tp_pdf_url} target="_blank" rel="noopener noreferrer"
                  className="flex items-center justify-between bg-slate-900/60 border border-slate-800 rounded-xl p-4 hover:border-blue-500/40 transition-colors">
                  <span className="text-sm font-semibold text-slate-200">Travaux Pratiques</span>
                  <span className="text-xs font-bold uppercase text-blue-400 bg-blue-500/10 px-3 py-1.5 rounded-lg">Télécharger</span>
                </a>
              )}
            </div>
          )}
        </div>

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-4 h-fit">
          <h3 className="text-xs font-semibold uppercase text-slate-500 tracking-wide mb-4 px-2">Programme du cours</h3>
          <div className="space-y-1">
            {course.lessons.map((lesson, index) => (
              <button
                key={lesson.id}
                onClick={() => setActiveLessonIndex(index)}
                className={`w-full text-left flex items-center justify-between gap-3 px-3 py-3 rounded-lg text-sm transition-colors ${
                  index === activeLessonIndex ? 'bg-blue-500/10 text-blue-400' : 'text-slate-300 hover:bg-slate-800/60'
                }`}
              >
                <span className="flex-1">{lesson.title}</span>
                <span className="text-xs font-mono text-slate-500 shrink-0">{lesson.duration}</span>
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};
export default CoursePlayer;
